        '.switch input:checked + .switch-slider::before{transform:translateX(24px)}' +
        '.seg{display:flex;gap:6px;padding:5px;border-radius:14px;background:rgba(var(--surface-rgb),.6);border:1px solid var(--border);flex:none}' +
        '.seg button{border:none;background:transparent;font:inherit;font-size:13px;font-weight:600;padding:8px 16px;border-radius:10px;cursor:pointer;color:var(--muted);transition:.18s}' +
        '.seg button.on{background:linear-gradient(135deg,var(--primary),var(--primary-dark));color:#fff;box-shadow:0 6px 16px -10px rgba(var(--primary-rgb),.9)}' +
        '.tip{padding:12px 16px;border-radius:14px;font-size:12px;line-height:1.6;color:var(--muted)}' +
        '.tip b{color:var(--text)}' +
        '</style></head><body><div class="wrap">' +
