/* ===== 运维面板 ===== */

/* 青橙小说 运维面板(精简版): 本源固定官方域, 无发布页线路轮换; 游客态免登录 */
function login(){ return 'ok'; }
function QC_tip(jv,msg,key,val){
  try{jv.toast(String(msg));}catch(e){}
  try{jv.longToast(String(msg));}catch(e){}
  try{if(key)jv.put(key,String(val==null?msg:val));}catch(e){}
  try{jv.reLoginView(false);}catch(e){try{jv.reUiView(false);}catch(e2){}}
  return String(msg);
}
function QC_get(jv,k,d){var v='';try{v=String(jv.get(k)||'');}catch(e){}return v||d;}
/* ① 检查登录状态: 本源游客态即可用, 显示票据与接口状态 */
function QC_checkLogin(jv){
  QC_tip(jv,'⏳ 正在检查接口与票据状态…','qcStatus','检查中…');
  var body='bookId=272713&needChapter=0&needRecommend=0',ok=false,ms=0,code='?',t0=Date.now();
  try{
    var u='https://goway.reader.yueyouxs.com'+QC_sign('/goway/goread/app/book/detail','',body);
