var OM_PLAYER = "https://art.v2player.top:8989/player/?";
var OM_AESKEY = "ABABEF777999CCCD";
var OM_LINES = [
  "https://www.omofuns.com", "https://cn.233dm.com",
  "https://cn.211dm.com", "https://cn.agekkkk.com"
];
var OM_LINE_NAMES = ["omofuns.com", "cn.233dm.com", "cn.211dm.com", "cn.agekkkk.com"];

// JsNull 三态归一：E 版 source.get 未设置返回 truthy 对象
function OM_g(v) {
  var s = String(v === undefined || v === null ? '' : v);
  if (s === '' || s === 'null' || s === 'undefined' || s === 'JsNull' || s === '[object Object]') return '';
  return s;
}
function OM_line(sv) {
  var v = '';
  try { v = OM_g(sv.get('om_line')); } catch (e) { }
  if (v.indexOf('http') !== 0) v = OM_DEFAULT;
  return v.replace(/\/+$/, '');
}
function OM_pub(sv) {
  var v = '';
  try { v = OM_g(sv.get('om_pub')); } catch (e) { }
  if (v.indexOf('http') !== 0) v = OM_PUB;
  return v.replace(/\/+$/, '');
}
function OM_toast(jv, msg) {
  try { jv.toast(msg); return; } catch (e) { }
  try { jv.longToast(msg); } catch (e2) { }
}
// 纯 JS Latin-1 base64（Rhino 里 java.base64Encode(byte[]) 会被字符串化成 [B@xxx）
function OM_b64(s) {
  var t = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=', o = '';
  for (var i = 0; i < s.length; i += 3) {
    var a = s.charCodeAt(i) & 255;
    var b = i + 1 < s.length ? s.charCodeAt(i + 1) & 255 : null;
    var c = i + 2 < s.length ? s.charCodeAt(i + 2) & 255 : null;
    var n = (a << 16) | ((b || 0) << 8) | (c || 0);
    o += t.charAt((n >> 18) & 63) + t.charAt((n >> 12) & 63)
      + (b === null ? '=' : t.charAt((n >> 6) & 63))
      + (c === null ? '=' : t.charAt(n & 63));
  }
  return o;
}
// MACCMS「系统安全验证」token：时间戳 XOR 16字节固定密钥 → Latin-1 → base64
function OM_token() {
  var key = [0x4e, 0x3f, 0xa9, 0xc2, 0x12, 0x7d, 0x88, 0xef,
             0x55, 0xaa, 0x0b, 0xcd, 0xde, 0xad, 0xbe, 0xef];
  var ts = String(Date.now()), p = '';
  for (var i = 0; i < ts.length; i++) p += String.fromCharCode(ts.charCodeAt(i) ^ key[i % 16]);
  return OM_b64(p);
}
// 过盾：POST verify_check 种 Cookie。type 取 search/show；成功后同域全站放行。
function OM_pass(jv, line, type) {
  var t = type || 'search';
  var u = line.replace(/\/+$/, '') + '/index.php/ajax/verify_check?type=' + t;
  var tok = OM_token();
  var hd = {
    'Content-Type': 'application/x-www-form-urlencoded',
    'Referer': line.replace(/\/+$/, '') + '/',
    'X-Requested-With': 'XMLHttpRequest',
    'User-Agent': OM_UA,
    'Origin': line.replace(/\/+$/, '')
  };
  try {
    var r = jv.post(u, 'i=' + encodeURIComponent(tok), hd);
    var b = String(r.body());
    return b.indexOf('"code":1') >= 0 || b.indexOf('"code": 1') >= 0 || /"msg"\s*:\s*"ok"/.test(b);
  } catch (e) { return false; }
}
// 发布页线路解析：eval 混淆脚本取 encodedLinks → base64 解码
function OM_fetchLines(jv, pubUrl) {
  var h = String(jv.ajax(pubUrl));
  var re = /<script>([\w\W]*?)<\/script>/g, m, code = '';
  while ((m = re.exec(h)) !== null) code = m[1];
  if (!code || code.indexOf('encodedLinks') < 0) return { err: '发布页结构变化，未找到线路数组', html: h.slice(0, 200) };
  var window = this, document = {};
  var arr;
  try { eval(code); arr = encodedLinks; } catch (e) { return { err: '发布页脚本执行失败：' + e }; }
  if (!arr || !arr.length) return { err: '发布页线路数组为空' };
  var out = [], seen = {};
  for (var i = 0; i < arr.length; i++) {
    var parts = String(arr[i]).split('|'), u = '';
    try { u = String(jv.base64Decode(parts[0])); } catch (e2) { }
    u = u.replace(/\/+$/, '');
    if (u.indexOf('http') !== 0 || seen[u]) continue;
    seen[u] = 1;
    out.push({ u: u, n: parts[1] || u.replace(/^https?:\/\//, '') });
  }
  return { lines: out };
}
// 线路探活三判据：code 200-399 + body 足够长 + 非异常堆栈串
function OM_probeOne(jv, u) {
  var t = Date.now();
  try {
    var r = jv.ajax(u + '/');
    var raw = r && r.raw && typeof r.raw === 'function' ? r.raw() : null;
    var code = 0;
    try { code = raw ? raw.code() : 0; } catch (e0) { }
    var b = String(r.body ? r.body() : r);
    var ok = (code >= 200 && code < 400 || code === 0) && b.length > 20000
      && !(b.length < 3000 && /Exception|Error|堆栈/.test(b));
    return { u: u, ms: Date.now() - t, ok: ok, len: b.length };
  } catch (e) { return { u: u, ms: Date.now() - t, ok: false, err: String(e) }; }
}
// 保存线路池：每个按钮一个键 om_s1..om_s8 + 池数量 om_sn
function OM_saveLines(sv, lines) {
  var n = Math.min(lines.length, 8);
  try {
    sv.put('om_sn', String(n));
    for (var i = 0; i < 8; i++) sv.put('om_s' + (i + 1), i < n ? lines[i].u : '');
    sv.put('om_lines', JSON.stringify(lines.slice(0, n)));
    sv.put('om_line', lines[0].u);
  } catch (e) { }
  return n;
}
function OM_loadLines(sv) {
  var arr = [];
  try {
    var raw = OM_g(sv.get('om_lines'));
    if (raw) { var p = JSON.parse(raw); if (p && p.length) arr = p; }
  } catch (e) { }
  if (!arr.length) {
    var n = 0;
    try { n = parseInt(OM_g(sv.get('om_sn')), 10) || 0; } catch (e2) { }
    for (var i = 1; i <= n; i++) {
      var u = ''; try { u = OM_g(sv.get('om_s' + i)); } catch (e3) { }
      if (u.indexOf('http') === 0) arr.push({ u: u, n: u.replace(/^https?:\/\//, '') });
    }
  }
  if (!arr.length) for (var k = 0; k < OM_LINES.length; k++) arr.push({ u: OM_LINES[k], n: OM_LINE_NAMES[k] });
  return arr;
}
function OM_speedKey(i) { return 'om_sp' + (i + 1); }
function OM_lineLabel(sv, i) {
  var arr = OM_loadLines(sv);
  if (i >= arr.length) return '（空位 ' + (i + 1) + '）';
  var sp = ''; try { sp = OM_g(sv.get(OM_speedKey(i))); } catch (e) { }
  var mark = sp.indexOf('⚡') === 0 ? '⚡' : '';
  return (mark ? '⚡ ' : '') + arr[i].n + ' ' + (sp || '未测速');
}
// 站点的书详情相对 URL 列表规则公共选择器
var OM_LIST = 'ul.BIaC_ACJijja > li';

