                    try { notify('清晰度切换失败，已保留原清晰度'); } catch (e) {}
                    try { oldVideo.muted = false; } catch (e) {}
                };

                const start = () => {
                    try {
                        const nh = new Hls({
                            enableWorker: true,
                            lowLatencyMode: true,
                            backBufferLength: 30,
                            maxBufferLength: 20,
                            liveSyncDurationCount: 3,
